/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p %s bytes\\n' | sort && printf '\\nffmpeg:\\n' && command -v ffmpeg && ffmpeg -version | head -3 && printf '\\npython libs:\\n' && python - <<'PY'
mods=['cv2','PIL','numpy','imageio','moviepy','scipy']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',e)
PY"

